import { updateUser } from "@/api/safeDanger/claimExpertPool";
import UserTable from "./userTable.vue";
export default {
  name: "",
  components: {
    UserTable: UserTable
  },
  props: ['formData'],
  data: function data() {
    return {
      loading: false,
      modelData: {},
      addVisible: false,
      // 校验
      rules: {
        realName: [{
          required: true,
          message: '必填:用户姓名',
          trigger: 'blur'
        }]
      }
    };
  },
  watch: {
    'formData': function formData(newVal, oldVal) {
      if (newVal) {
        var newData = JSON.parse(JSON.stringify(newVal));
        for (var newDataKey in newData) {
          if (newData[newDataKey]) {
            this.modelData[newDataKey] = newData[newDataKey];
          }
        }
      }
    }
  },
  mounted: function mounted() {
    this.modelData = JSON.parse(JSON.stringify(this.formData));
  },
  methods: {
    handelUpdate: function handelUpdate() {
      var _this = this;
      this.$refs.queryForm.validate(function (valid) {
        if (valid) {
          _this.loading = true;
          updateUser(_this.modelData).then(function (res) {
            _this.msgSuccess("修改成功");
            _this.$emit('closeEdit', true);
          }).finally(function () {
            _this.loading = false;
          });
        }
      });
    },
    handleSel: function handleSel(vis) {
      if (vis) {
        this.$emit('editChoose');
        if (this.$refs.esel) {
          this.$refs.esel.visible = false;
        }
      }
    },
    handelCancel: function handelCancel() {
      this.$emit('closeEdit');
    },
    closeDialog: function closeDialog(isRefresh) {}
  }
};
